import {parseCases, replay, parseManifest, testStatus, discoveryDraft} from './refund.mjs';
import {parsePrUrl, validateMetadata, currentSnapshotState} from './model.mjs';

const $ = id => document.getElementById(id);
const EXISTING = 'src/test/java/example/refunds/ExistingRefundContractTest.java';
const PROPOSED = 'src/test/java/example/refunds/PartialRefundContractTest.java';
let fixture, activeFile = 'contracts', drafts = {}, originals = {}, metadataRequest;
const names = {contracts:'contracts.json',intent:'change-intent.md',proposed:'change-contracts.json',cases:'replay-cases.json',source:'src/main/java/example/refunds/RefundService.java',existingTests:EXISTING,newTests:PROPOSED,probe:'GeneratedRefundProbeTest.java',discovery:'Legacy test inventory',discoveryDraft:'discovery-proposal.json'};
const purposes = {
  contracts:'Standing system invariants. All declared checks apply, irrespective of diff size or implementation structure.',
  intent:'What should change, why it should change, and what must remain true. Free text is context, not an executable oracle.',
  proposed:'Proposed acceptance checks for partial refunds. Passing these cannot waive a standing invariant.',
  cases:'Editable sequential traces for the browser model. Amounts are integer minor units in one currency.',
  source:'Recorded fixture source, not an editable code-execution surface. Compare the legacy and candidate source identities below.',
  existingTests:'Existing behavior checks reused unchanged across all three implementation fixtures.',
  newTests:'Proposed behavior checks. Failure on the legacy implementation means the new behavior is not present there.',
  probe:'Temporary candidate oracle, generated by a reviewed template and executed locally on broken and corrected fixtures. It does not approve itself.',
  discovery:'Candidates from existing test descriptions and exact source locations. This fixture inventory does not infer arbitrary Java business semantics.',
  discoveryDraft:'Unapproved contract proposal copied from test metadata. Review ownership, intent, assumptions, and counterexamples before adoption.'
};
const editable = new Set(['contracts','intent','proposed','cases','discoveryDraft']);
function variant() {return $('subject').value;}
function content(file) {
  if (editable.has(file)) return drafts[file] ?? '';
  if (file === 'source') return fixture.variants[variant()].source;
  if (file === 'probe') return fixture.probe.source;
  return fixture.test_sources[file === 'existingTests' ? EXISTING : PROPOSED];
}
function feedback() {
  if (!fixture) return;
  const dirty = ['contracts','proposed','intent','discoveryDraft'].filter(file => drafts[file] !== (originals[file] ?? ''));
  $('draft-status').textContent = dirty.length ? `Draft changed: ${dirty.map(file => names[file]).join(', ')}. Recorded JUnit rows still refer to the original fixture contracts and intention; owner review and matching evidence are required.` : 'Standing contracts and proposed behavior are separate. Fixture ownership is illustrative; no production approval is granted.';
  try {
    if (['contracts','proposed','discoveryDraft'].includes(activeFile)) {parseManifest(drafts[activeFile]); $('editor-feedback').textContent = 'Version 1 JSON draft · CLI also accepts YAML · use contracts validate for full schema/source checks.';}
    else if (activeFile === 'cases') {$('editor-feedback').textContent = `${parseCases(drafts.cases).length} replay cases · local model only`;}
    else $('editor-feedback').textContent = editable.has(activeFile) ? 'Draft stays in this tab. It does not replace approved policy or modify the repository.' : 'Read-only recorded source.';
  } catch(error) {$('editor-feedback').textContent = error.message;}
}
function openFile(file) {
  activeFile = file;
  $('file-name').textContent = names[file];
  $('file-purpose').textContent = purposes[file];
  $('editor').hidden = file === 'discovery'; $('discovery').hidden = file !== 'discovery';
  $('restore').hidden = !editable.has(file);
  $('download').hidden = file === 'discovery';
  $('file-status').textContent = file === 'contracts' ? 'STANDING / DRAFT EDITOR' : editable.has(file) ? 'DRAFT' : file === 'discovery' || file === 'probe' ? 'CANDIDATE' : 'RECORDED SOURCE';
  if (file !== 'discovery') {$('editor').readOnly = !editable.has(file); $('editor').value = content(file);}
  document.querySelectorAll('[data-file]').forEach(button => button.setAttribute('aria-pressed',String(button.dataset.file === file)));
  feedback();
}
document.querySelectorAll('[data-file]').forEach(button => button.addEventListener('click', () => {if (fixture) openFile(button.dataset.file);}));
$('editor').addEventListener('input', () => {
  if (!editable.has(activeFile)) return;
  drafts[activeFile] = $('editor').value;
  if (activeFile === 'cases') {$('replay-status').textContent = 'Replay inputs changed. Compare again.'; $('replay-rows').replaceChildren(); $('trace-output').textContent = '';}
  feedback();
});
$('restore').addEventListener('click', () => {
  drafts[activeFile] = originals[activeFile] ?? '';
  if (activeFile === 'discoveryDraft') {$('discovery-draft-button').hidden = true; openFile('discovery');}
  else {openFile(activeFile); if (activeFile === 'cases') compare();}
});
$('subject').addEventListener('change', () => {if (!fixture) return; if (activeFile === 'source') openFile('source'); compare();});
$('compare').addEventListener('click', compare);
$('download').addEventListener('click', () => {
  if (!fixture || activeFile === 'discovery') return;
  const url = URL.createObjectURL(new Blob([content(activeFile)],{type:'text/plain;charset=utf-8'}));
  const anchor = document.createElement('a'); anchor.href = url; anchor.download = names[activeFile].split('/').pop(); anchor.click();
  setTimeout(() => URL.revokeObjectURL(url),1000);
});
function cell(text, state) {
  const td = document.createElement('td'); td.textContent = text;
  if (state) {td.className = 'status'; td.dataset.state = state;}
  return td;
}
function group(label, detail) {
  const row = document.createElement('tr'); row.className = 'group-row';
  const td = cell(label); td.colSpan = 3;
  const note = document.createElement('span'); note.textContent = detail; td.append(note); row.append(td); return row;
}
function compare() {
  if (!fixture) return;
  $('check-rows').replaceChildren();
  const standing = JSON.parse(fixture.contracts), proposed = JSON.parse(fixture.proposed);
  let failedStanding = 0;
  for (const [manifest,role] of [[standing,'standing invariant'],[proposed,'proposed behavior']]) {
    for (const contract of manifest.contracts) {
      $('check-rows').append(group(contract.id,`${role} · ${contract.expectation}`));
      for (const test of contract.tests) {
        const base = testStatus(fixture,'legacy',test.id), head = testStatus(fixture,variant(),test.id);
        if (role === 'standing invariant' && head !== 'passed') failedStanding++;
        const row = document.createElement('tr'), name = document.createElement('td'); name.className = 'check-name';
        const button = document.createElement('button'); button.textContent = test.id.split('.').pop(); button.title = test.id; button.addEventListener('click', () => openFile(test.id.includes('Existing') ? 'existingTests' : 'newTests')); name.append(button);
        row.append(name,cell(base,base),cell(head,head)); $('check-rows').append(row);
      }
    }
  }
  $('check-rows').append(group('TEMPORARY PROBE','candidate verifier · not added to standing policy'));
  const probe = document.createElement('tr'); probe.append(cell('GeneratedRefundProbeTest.cumulativePartialRefundCounterexample'),cell('not run'),cell(fixture.probe.runs[variant()]?.status ?? 'not run',fixture.probe.runs[variant()]?.status)); $('check-rows').append(probe);
  $('comparison-summary').dataset.state = failedStanding ? 'failed' : 'passed';
  $('comparison-summary').textContent = failedStanding ? `${failedStanding} standing check failed. New behavior passing does not establish preservation.` : 'Standing checks passed for this recorded fixture. Proposed behavior and operational gaps remain separate.';
  $('record-origin').textContent = `Recorded local JUnit · ${fixture.captured_at.slice(0,10)} · no trusted CI receipt`;
  $('provenance').textContent = `legacy source sha256: ${fixture.variants.legacy.source_sha256}\ncandidate source sha256: ${fixture.variants[variant()].source_sha256}\nstanding/proposed test inventory sha256: ${fixture.oracle_sha256}\ntemporary probe sha256: ${fixture.probe.sha256}\n\n${fixture.assumptions}\nThis page reads captured JUnit observations. Compare does not compile Java or authenticate a CI receipt.\nReproduce: python3 scripts/refund-showcase.py --output .undertow/refund-run`;
  $('replay-rows').replaceChildren();
  try {
    const cases = parseCases(drafts.cases), traces = [];
    for (const item of cases) {
      const base = replay(item,'legacy'), head = replay(item,variant());
      const row = document.createElement('tr'); row.append(cell(item.id),cell(String(item.captured_minor)),cell(String(base.refunded_minor)),cell(String(head.refunded_minor)),cell(head.cap_holds ? 'holds' : 'violated',head.cap_holds ? 'passed' : 'failed')); $('replay-rows').append(row);
      traces.push({case:item.id,legacy:base.operations,candidate:head.operations});
    }
    $('replay-status').textContent = `${cases.length} input traces evaluated in the browser model. Recorded JUnit and policy bindings are unchanged.`;
    $('trace-output').textContent = JSON.stringify(traces,null,2);
  } catch(error) {$('replay-status').textContent = `Replay incomplete: ${error.message}`; $('trace-output').textContent = '';}
  discovery();
  feedback();
}
function discovery() {
  $('discovery').replaceChildren();
  for (const candidate of fixture.discovery) {
    const section = document.createElement('article'); section.className = 'candidate';
    const head = document.createElement('div'); head.className = 'candidate-head';
    const p = document.createElement('p'); p.textContent = candidate.expectation;
    const button = document.createElement('button'); button.textContent = 'Open as draft'; button.addEventListener('click', () => {
      drafts.discoveryDraft = JSON.stringify(discoveryDraft(candidate),null,2); $('discovery-draft-button').hidden = false; openFile('discoveryDraft');
    }); head.append(p,button);
    const source = document.createElement('code'); source.textContent = `${candidate.source}:${candidate.line}\n${candidate.test_id}`;
    const note = document.createElement('small'); note.textContent = `candidate · @DisplayName metadata · legacy ${testStatus(fixture,'legacy',candidate.test_id)} / candidate ${testStatus(fixture,variant(),candidate.test_id)} · ${candidate.limitation}`;
    section.append(head,source,note); $('discovery').append(section);
  }
}
try {
  const response = await fetch('evidence/refund-fixture.json');
  if (!response.ok) throw new Error('Refund capture unavailable.');
  fixture = await response.json();
  if (fixture.kind !== 'recorded-local-junit' || fixture.trusted_ci_import !== false || !fixture.probe) throw new Error('Unexpected evidence kind.');
  originals = {contracts:fixture.contracts,proposed:fixture.proposed,intent:fixture.intent,cases:fixture.cases,discoveryDraft:''}; drafts = {...originals};
  discovery(); openFile('contracts'); $('compare').disabled = false; compare();
} catch(error) {$('comparison-summary').textContent = `Evidence unavailable: ${error.message}`; $('file-name').textContent = 'Fixture unavailable';}

// Preserve the earlier real public CI reference without making it the primary product model.
let ticketLoaded = false;
$('ticket-reference').addEventListener('toggle', async () => {
  if (!$('ticket-reference').open || ticketLoaded) return;
  $('ticket-results').replaceChildren();
  try {
    const catalog = await (await fetch('evidence/catalog.json')).json();
    for (const name of ['broken','fixed','missing']) {
      const report = await (await fetch(`evidence/${name}/contracts.json`)).json(), item = catalog.cases[name];
      if (report.head_sha !== item.head || report.policy.policy_commit !== catalog.policyCommit) throw new Error('Ticket subject mismatch.');
      const row = document.createElement('div'), label = document.createElement('span'); label.textContent = `${name} · ${report.verification}`;
      const links = document.createElement('span');
      for (const [text,url] of [['PR ↗',item.pr],['JSON ↗',`evidence/${name}/contracts.json`]]) {const a = document.createElement('a'); a.href = url; a.textContent = text; a.target = '_blank'; a.rel = 'noreferrer'; links.append(a);}
      row.append(label,links); $('ticket-results').append(row);
    }
    ticketLoaded = true;
  } catch(error) {$('ticket-results').textContent = error.message;}
});
$('pr-url').addEventListener('input', () => {metadataRequest?.abort(); metadataRequest = undefined; $('pr-status').textContent = '';});
$('pr-form').addEventListener('submit', async event => {
  event.preventDefault(); metadataRequest?.abort(); metadataRequest = undefined;
  let request;
  try {request = parsePrUrl($('pr-url').value);} catch(error) {$('pr-status').textContent = error.message; return;}
  const controller = new AbortController(); metadataRequest = controller;
  const timeout = setTimeout(() => controller.abort(),8000); $('pr-status').textContent = 'Reading public metadata…';
  try {
    const response = await fetch(request.api,{signal:controller.signal,credentials:'omit',redirect:'error',headers:{Accept:'application/vnd.github+json'}});
    if (!response.ok) throw new Error(`GitHub HTTP ${response.status}; no contract assessment produced.`);
    const metadata = validateMetadata(await response.json(),request);
    let freshness = '';
    if (request.repository.toLowerCase() === 'alpercandemir/undertow-showcase' && ['1','2'].includes(request.number)) {
      const catalog = await (await fetch('evidence/catalog.json',{signal:controller.signal})).json();
      const snapshot = catalog.cases[request.number === '1' ? 'broken' : 'fixed'];
      freshness = currentSnapshotState(snapshot,metadata) === 'same_subject' ? ' Archived head/target match; CI evidence was not refreshed.' : ' Archived head/target differ: the snapshot is stale for this PR.';
    }
    if (metadataRequest === controller) $('pr-status').textContent = `${metadata.title} · head ${metadata.head} · metadata only, not contract verification.${freshness}`;
  } catch(error) {if (metadataRequest === controller) $('pr-status').textContent = error.name === 'AbortError' ? 'Metadata request timed out.' : error.message;}
  finally {clearTimeout(timeout);}
});
